-- Generated by tools/write_source_queries.py from focus/data/datasets.py. Read-only; explicit projection (S05).
-- Raw clock intervals (S06 FOCUS_FN_ClockObservation) for the latest COMPLETE source run.
SELECT co.SourceEventKey AS SOURCE_EVENT_KEY, co.LineNumber AS LINE_NUMBER, co.NativeSoi AS NATIVE_SOI,
 co.PersonKey AS PERSON_KEY, co.EpisodeKey AS EPISODE_KEY, co.Team AS TEAM, co.ReworkClass AS REWORK_CLASS,
 co.StartUtc AS START_UTC, co.EndUtc AS END_UTC, co.SourceRevision AS SOURCE_REVISION, co.IsVoided AS IS_VOIDED
FROM WEB_APP.FOCUS_FN_ClockObservation co
WHERE co.RunId = (SELECT TOP 1 h.RunId FROM WEB_APP.FOCUS_FN_SourceHead h ORDER BY h.UpdatedAtUtc DESC);
